INSERT INTO "articles" ("id", "author_id", "category_id", "title", "slug", "excerpt", "body", "cover_image", "status", "revision_note", "published_at", "created_at", "updated_at", "author_name", "updated_by", "updated_by_name") VALUES (3, NULL, 2, 'Gelar Karya P5: Kreativitas Siswa dalam Mengolah Sampah', 'gelar-karya-p5-kreativitas-siswa-dalam-mengolah-sampah', 'Siswa SMPN 1 Gondang menunjukkan kreativitas melalui kegiatan Gelar Karya P5 bertema pengolahan sampah menjadi produk yang bermanfaat dan bernilai guna.', '<h3>Mengembangkan Kreativitas dan Kepedulian Lingkungan</h3><p>SMPN 1 Gondang mengadakan kegiatan Gelar Karya Projek Penguatan Profil Pelajar Pancasila (P5) dengan tema "Sampahku Inspirasi". Kegiatan ini menjadi wadah bagi peserta didik untuk menunjukkan kreativitas dan kepedulian terhadap lingkungan.</p><h3>Mengolah Sampah Menjadi Karya Bermanfaat</h3><p>Dalam kegiatan ini, peserta didik mengembangkan berbagai ide kreatif dengan memanfaatkan barang bekas dan bahan yang mudah ditemukan di lingkungan sekitar. Berbagai bahan tersebut diolah menjadi kerajinan dan produk yang memiliki nilai guna serta nilai estetika.</p><h3>Meningkatkan Kerja Sama dan Kreativitas</h3><p>Selain menghasilkan karya, kegiatan ini juga melatih peserta didik untuk bekerja sama, bertanggung jawab, berpikir kreatif, dan menyelesaikan permasalahan secara bersama-sama.</p><h3>Menumbuhkan Kepedulian terhadap Lingkungan</h3><p>Melalui kegiatan Gelar Karya P5, diharapkan peserta didik semakin memahami pentingnya menjaga kebersihan lingkungan, mengurangi sampah, serta menerapkan kebiasaan hidup ramah lingkungan dalam kehidupan sehari-hari.</p><p>Kegiatan ini menjadi salah satu bentuk pembelajaran bermakna yang menghubungkan pengetahuan dengan kehidupan nyata.</p>', 'media/QYEjY1UL0IsUSkNpXPdphPu7a2C4hxYM3yMPswFS.jpg', 'published', NULL, '2026-11-08 14:45:00', '2026-11-08 16:46:39', '2026-11-08 16:46:39', 'Admin 1', NULL, NULL);
