INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (23, NULL, 'extracurricular', 'OSIS (Organisasi Siswa Intra Sekolah)', 'osis-organisasi-siswa-intra-sekolah-ay5mw', 'Wadah organisasi siswa untuk mengembangkan jiwa kepemimpinan, kedisiplinan, tanggung jawab, dan kreativitas dalam lingkungan sekolah.', 'OSIS merupakan organisasi resmi siswa yang menjadi sarana bagi peserta didik untuk belajar berorganisasi, bekerja sama, dan mengembangkan kemampuan kepemimpinan. Melalui berbagai program kerja dan kegiatan sekolah, anggota OSIS dilatih untuk bertanggung jawab, berkomunikasi, mengambil keputusan, serta menyampaikan aspirasi siswa. OSIS juga berperan aktif dalam membantu pelaksanaan kegiatan sekolah, seperti peringatan hari besar, kegiatan sosial, perlombaan, dan acara kesiswaan lainnya.', 'media/loSZwPEkhw7vCx1TSZvt9DVSDIkmsvqNMouaaAw2.jpg', NULL, NULL, NULL, NULL, 1, 1, '2026-11-07 21:32:55', '2026-11-07 21:32:55', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (24, NULL, 'extracurricular', 'PMR (Palang Merah Remaja)', 'pmr-palang-merah-remaja-wuxgo', 'Kegiatan kepalangmerahan yang membentuk siswa agar peduli terhadap sesama, memiliki jiwa kemanusiaan, dan memahami pertolongan pertama.', 'PMR merupakan ekstrakurikuler yang memberikan pengetahuan dan keterampilan dasar dalam bidang kesehatan dan kemanusiaan. Anggota PMR mendapatkan pembelajaran mengenai pertolongan pertama, kesehatan remaja, kebersihan lingkungan, serta kesiapsiagaan menghadapi keadaan darurat. Kegiatan ini bertujuan menumbuhkan sikap peduli, sukarela, disiplin, dan tanggung jawab dalam membantu sesama.', 'media/g0XlwbdXaFrGGXE3YA1rjZoXdhdpqOGrPiFIv8SA.jpg', NULL, NULL, NULL, NULL, 1, 2, '2026-11-07 21:33:46', '2026-11-07 21:33:46', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (25, NULL, 'extracurricular', 'PRAMUKA', 'pramuka-ca12k', 'Kegiatan pendidikan karakter yang melatih kemandirian, kedisiplinan, kerja sama, dan keterampilan melalui aktivitas kepramukaan.', 'Pramuka merupakan kegiatan ekstrakurikuler yang bertujuan membentuk karakter siswa melalui berbagai aktivitas yang menarik, mendidik, dan menantang. Kegiatan meliputi latihan baris-berbaris, tali-temali, sandi, penjelajahan, perkemahan, serta keterampilan bertahan dan beradaptasi di alam. Melalui Pramuka, siswa dilatih menjadi pribadi yang mandiri, bertanggung jawab, disiplin, memiliki jiwa kepemimpinan, serta mampu bekerja sama dalam kelompok.', 'media/RxrrF44f0u7LchINNJ29uU7YBcuRfpTuuXic5B5W.jpg', NULL, NULL, NULL, NULL, 1, 3, '2026-11-07 21:34:43', '2026-11-07 21:34:43', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (26, NULL, 'extracurricular', 'KARAWITAN', 'karawitan-d8r7w', 'Kegiatan seni musik tradisional Jawa yang mengenalkan dan melestarikan budaya melalui permainan alat musik gamelan.', 'Karawitan merupakan ekstrakurikuler seni budaya yang berfokus pada pembelajaran musik tradisional Jawa. Siswa diperkenalkan dengan berbagai alat musik gamelan, seperti saron, bonang, kendang, gong, dan kenong. Melalui latihan rutin, siswa belajar memainkan alat musik secara harmonis, memahami irama, serta bekerja sama dalam menghasilkan pertunjukan musik tradisional. Kegiatan ini juga menjadi sarana untuk menumbuhkan kecintaan terhadap budaya daerah dan melestarikan warisan seni tradisional.', 'media/d6XgLphfQCCDucI2lxgkxeseOZReNyhM6JgHvWvi.jpg', NULL, NULL, NULL, NULL, 1, 4, '2026-11-07 21:35:30', '2026-11-07 21:35:30', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (27, NULL, 'extracurricular', 'TARI', 'tari-4bpnf', 'Kegiatan seni gerak yang mengembangkan kreativitas, ekspresi, keluwesan gerakan, dan kecintaan terhadap budaya.', 'Ekstrakurikuler tari merupakan kegiatan yang memberikan kesempatan kepada siswa untuk mengenal dan mempelajari berbagai jenis tarian tradisional maupun kreasi modern. Siswa dilatih memahami gerakan, irama, pola lantai, ekspresi, dan teknik dasar menari. Selain meningkatkan kreativitas dan kepercayaan diri, kegiatan ini juga menjadi wadah bagi siswa untuk mengembangkan bakat seni serta menampilkan hasil latihan dalam berbagai acara dan pertunjukan sekolah.', 'media/LAo80zYLh4fVDPZqdQJB8xzATS1lKNuwc7YmyXOR.jpg', NULL, NULL, NULL, NULL, 1, 5, '2026-11-07 21:36:30', '2026-11-07 21:36:30', 'Admin 1');
