INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (45, NULL, 'gallery', 'Pemilihan Ketua Osis', 'pemilihan-ketua-osis-qilli', '', NULL, 'media/JK6AhXIJB8KRSU5MHe98KF1JtOq2bLX9zhVH2xk0.jpg', NULL, NULL, NULL, NULL, 1, 5, '2026-11-07 22:10:18', '2026-11-07 22:10:18', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (46, NULL, 'learning_activity', 'Pembelajaran Berbasis Proyek', 'pembelajaran-berbasis-proyek-9r1wd', 'Kegiatan belajar melalui proyek individu maupun kelompok untuk meningkatkan kreativitas, kerja sama, dan kemampuan berpikir kritis.', 'Pembelajaran berbasis proyek merupakan metode pembelajaran yang melibatkan peserta didik dalam menyelesaikan suatu proyek. Peserta didik dilatih untuk berpikir kritis, kreatif, bekerja sama, dan menyelesaikan permasalahan secara mandiri.', 'media/NaDDzrsM8xiFiugQFn7EYqGGBZ7e9Ye0wsvUddZk.jpg', NULL, 'Ruang Kelas', '2026-11-06 00:00:00', NULL, 1, 1, '2026-11-08 16:10:22', '2026-11-08 16:10:22', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (47, NULL, 'education_calendar', 'Kalender Pendidikan', 'kalender-pendidikan-7cwty', '', 'Kalender Pendidikan Tahun Ajaran 2026/2027 merupakan pedoman pelaksanaan kegiatan akademik di SMPN 1 Gondang. Kalender ini memuat jadwal awal tahun pelajaran, kegiatan belajar mengajar, asesmen tengah semester, asesmen akhir semester, pembagian rapor, kegiatan libur sekolah, serta akhir tahun pelajaran.'||char(10)||''||char(10)||'Dengan adanya kalender pendidikan, peserta didik, guru, dan tenaga kependidikan dapat mengetahui serta mempersiapkan berbagai kegiatan sekolah secara terencana dan teratur.', 'media/IWQQ7BQ10Ncc3iiWVrQdlaPWbWAabjc6ARLoZ2S1.png', NULL, NULL, NULL, '[]', 1, 0, '2026-11-08 16:15:19', '2026-11-08 16:17:45', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (48, NULL, 'academic_program', 'Program Ekstrakurikuler', 'program-ekstrakurikuler-huamk', '', 'Program ekstrakurikuler SMPN 1 Gondang merupakan kegiatan pengembangan minat dan bakat peserta didik di luar jam pembelajaran. Kegiatan ini bertujuan meningkatkan kreativitas, kedisiplinan, tanggung jawab, kerja sama, serta kemampuan peserta didik dalam bidang akademik maupun nonakademik.'||char(10)||''||char(10)||'Berbagai kegiatan ekstrakurikuler yang tersedia meliputi Pramuka, PMR, OSIS, Paskibra, seni tari, karawitan, olahraga, BTQ, paduan suara, dan kegiatan lainnya.', 'media/8aSo1Ib2peFvwx6u8DMwJ4E56gp08Klslba2LE1j.jpg', NULL, NULL, NULL, '{"program_category":"kokurikuler"}', 1, 0, '2026-11-08 16:19:20', '2026-11-08 16:19:20', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (49, NULL, 'academic_assessment', 'Informasi Asesmen Akademik', 'informasi-asesmen-akademik-tkntk', '', 'Asesmen akademik SMPN 1 Gondang merupakan kegiatan penilaian untuk mengetahui perkembangan, kemampuan, dan pencapaian kompetensi peserta didik selama proses pembelajaran.'||char(10)||''||char(10)||'Pelaksanaan asesmen meliputi penilaian harian, tugas, proyek, asesmen tengah semester, dan asesmen akhir semester. Hasil asesmen digunakan sebagai bahan evaluasi untuk meningkatkan kualitas pembelajaran serta membantu peserta didik mencapai hasil belajar yang optimal.', 'media/7BHWi2vqgsSgUKgL88YzjHrIwXH7XTFwz0i73NBv.png', NULL, NULL, NULL, '[]', 1, 0, '2026-11-08 16:20:20', '2026-11-08 16:20:20', 'Admin 1');
INSERT INTO "content_entries" ("id", "author_id", "type", "title", "slug", "excerpt", "body", "image_path", "document_path", "location", "starts_at", "metadata", "published", "sort_order", "created_at", "updated_at", "author_name") VALUES (50, NULL, 'announcement', 'Gelar Karya P5 "Sampahku Inspirasi"', 'gelar-karya-p5-sampahku-inspirasi-rt61w', 'SMPN 1 Gondang menyelenggarakan kegiatan Gelar Karya Projek Penguatan Profil Pelajar Pancasila (P5) dengan tema "Sampahku Inspirasi".'||char(13)||char(10)||''||char(13)||char(10)||'Kegiatan ini merupakan bentuk kreativitas peserta didik dalam mengolah sampah menjadi berbagai produk yang memiliki nilai guna dan nilai estetika.'||char(13)||char(10)||''||char(13)||char(10)||'Melalui kegiatan ini, peserta didik diajak untuk meningkatkan kepedulian terhadap lingkungan, mengembangkan kreativitas, serta menerapkan kebiasaan hidup bersih dan ramah lingkungan.'||char(13)||char(10)||''||char(13)||char(10)||'Berbagai hasil karya siswa', 'SMPN 1 Gondang menyelenggarakan kegiatan Gelar Karya Projek Penguatan Profil Pelajar Pancasila (P5) dengan tema &quot;Sampahku Inspirasi&quot;.<br>'||char(13)||char(10)||'<br>'||char(13)||char(10)||'Kegiatan ini merupakan bentuk kreativitas peserta didik dalam mengolah sampah menjadi berbagai produk yang memiliki nilai guna dan nilai estetika.<br>'||char(13)||char(10)||'<br>'||char(13)||char(10)||'Melalui kegiatan ini, peserta didik diajak untuk meningkatkan kepedulian terhadap lingkungan, mengembangkan kreativitas, serta menerapkan kebiasaan hidup bersih dan ramah lingkungan.<br>'||char(13)||char(10)||'<br>'||char(13)||char(10)||'Berbagai hasil karya siswa ditampilkan dalam kegiatan gelar karya sebagai bentuk apresiasi terhadap ide, kreativitas, dan kerja sama peserta didik.', 'media/cT1B6ahuR36O33h7bQNMuY7d4a5L9MQPXWBzIp8D.jpg', NULL, NULL, '2026-11-14 00:00:00', NULL, 1, 3, '2026-11-08 16:23:21', '2026-11-08 16:23:21', 'Admin 1');
