INSERT INTO "site_settings" ("key", "value", "created_at", "updated_at") VALUES ('history', '"SMP Negeri 1 Gondang Tulungagung merupakan lembaga pendidikan yang berkomitmen mencetak generasi muda yang cerdas, berprestasi, berkarakter, dan berakhlak mulia. Dengan lingkungan belajar yang nyaman dan kondusif, sekolah terus mengembangkan potensi peserta didik melalui pendidikan berkualitas, kreativitas, kedisiplinan, serta pengembangan bakat dan minat."', '2026-11-02 05:36:17', '2026-11-02 05:50:57');
INSERT INTO "site_settings" ("key", "value", "created_at", "updated_at") VALUES ('vision', '"visi sekolah"', '2026-11-02 05:36:17', '2026-11-02 05:50:57');
