INSERT INTO "spmb_announcements" ("id", "title", "body", "starts_at", "published", "created_at", "updated_at") VALUES (1, 'Informasi Penerimaan Murid Baru Tahun Ajaran 2027/2028', 'SMPN 1 Gondang membuka Penerimaan Murid Baru (SPMB) Tahun Ajaran 2027/2028.'||char(13)||char(10)||''||char(13)||char(10)||'Calon peserta didik dan orang tua dapat memperoleh informasi mengenai persyaratan pendaftaran, prosedur seleksi, jadwal pelaksanaan, serta tahapan penerimaan murid baru melalui informasi resmi sekolah.'||char(13)||char(10)||''||char(13)||char(10)||'Pastikan seluruh persyaratan telah dipersiapkan sebelum melakukan pendaftaran.'||char(13)||char(10)||''||char(13)||char(10)||'Untuk informasi lebih lanjut, silakan menghubungi panitia SPMB SMPN 1 Gondang.', NULL, 1, '2026-11-08 16:36:21', '2026-11-08 16:36:21');
INSERT INTO "spmb_contacts" ("id", "name", "role", "phone", "office_hours", "note", "published", "sort_order", "created_at", "updated_at") VALUES (1, 'Admin SPMB SMPN 1 Gondang', 'Panitia Penerimaan Murid Baru', '0813-3229-4556', 'Senin–Jumat, 08.00–14.00 WIB', 'Hubungi Admin SPMB untuk mendapatkan informasi mengenai persyaratan, prosedur pendaftaran, jadwal, dan informasi penerimaan murid baru SMPN 1 Gondang.', 1, 1, '2026-11-08 16:43:40', '2026-11-08 16:43:40');
INSERT INTO "spmb_settings" ("id", "title", "school_year", "introduction", "schedule", "requirements", "steps", "documents", "quota", "fee_information", "registration_url", "poster_path", "published", "created_at", "updated_at", "status", "important_links", "poster_caption", "contact_whatsapp") VALUES (1, 'Penerimaan Murid Baru', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'spmb/posters/wDe7adLnoRKsjaohbo0WjnTPTS308DgHZwUIW2Lv.png', 0, '2026-11-07 22:12:55', '2026-11-08 16:41:52', 'preparation', '[{"title":"Daftar Sekarang","url":"https:\/\/example.com\/pendaftaran","description":"Tautan untuk melakukan pendaftaran calon murid baru SMPN 1 Gondang.","category":"registration","sort_order":1,"published":true,"id":"b6f3ab39-18c4-4583-868c-36e3ad52e6dc"},{"title":"Persyaratan SPMB","url":"https:\/\/example.com\/persyaratan","description":"Panduan tata cara pendaftaran murid baru secara lengkap.","category":"other","sort_order":2,"published":true,"id":"141cb3a4-4984-42f2-b8c0-7a2afc993c0b"}]', 'Poster Penerimaan Murid Baru (SPMB) SMPN 1 Gondang Tahun Ajaran 2027/2028.  Bergabunglah bersama SMPN 1 Gondang untuk meraih prestasi, mengembangkan potensi, serta membentuk karakter yang berakhlak dan berbudaya.  Dapatkan informasi mengenai persyara', NULL);
